const int pins[] = { {{P0}}, {{P1}}, {{P2}}, {{P3}}, {{P4}}, {{P5}}, {{P6}} };
const byte masks[] = { 0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F };
const bool commonAnode = false;

void setup() {
  for (int pin : pins) pinMode(pin, OUTPUT);
}

void loop() {
  for (int digit = 0; digit < 10; ++digit) {
    for (int s = 0; s < 7; ++s) {
      bool on = (masks[digit] & (1 << s)) != 0;
      digitalWrite(pins[s], (on != commonAnode) ? HIGH : LOW);
    }
    delay(400);
  }
}
